Object.assign(RR_TEXT_TRANSLATIONS.ja, { "While swimming": "水泳中", "Swimming": "水泳", "Swimming (3D maps)": "水泳（3Dマップ）", "Players can swim in deep water": "深い水の中を泳げる", "Float depth": "浮かぶ深さ", "tiles under the surface": "タイル（水面下）", "Splash sound": "水しぶきの音", "Shallower water is waded; deeper water is swum. Dash dives, Jump rises; at the surface Jump leaps out.": "浅い水は歩いて渡り、深い水は泳ぎます。ダッシュで潜り、ジャンプで浮上。水面ではジャンプで飛び出します。" });
Object.assign(RR_TEXT_TRANSLATIONS.es, { "While swimming": "Al nadar", "Swimming": "Nadando", "Swimming (3D maps)": "Natación (mapas 3D)", "Players can swim in deep water": "Los jugadores pueden nadar en agua profunda", "Float depth": "Profundidad de flotación", "tiles under the surface": "casillas bajo la superficie", "Splash sound": "Sonido de chapoteo", "Shallower water is waded; deeper water is swum. Dash dives, Jump rises; at the surface Jump leaps out.": "El agua poco profunda se vadea; la profunda se nada. Correr bucea, Saltar sube; en la superficie Saltar sale del agua." });
Object.assign(RR_TEXT_TRANSLATIONS['zh-Hant'], { "While swimming": "游泳時", "Swimming": "游泳", "Swimming (3D maps)": "游泳（3D 地圖）", "Players can swim in deep water": "玩家可在深水中游泳", "Float depth": "漂浮深度", "tiles under the surface": "格（水面下）", "Splash sound": "濺水音效", "Shallower water is waded; deeper water is swum. Dash dives, Jump rises; at the surface Jump leaps out.": "淺水涉水而過，深水需游泳。衝刺下潛，跳躍上浮；在水面時跳躍可躍出水面。" });
Object.assign(RR_TEXT_TRANSLATIONS['zh-Hans'], { "While swimming": "游泳时", "Swimming": "游泳", "Swimming (3D maps)": "游泳（3D 地图）", "Players can swim in deep water": "玩家可在深水中游泳", "Float depth": "漂浮深度", "tiles under the surface": "格（水面下）", "Splash sound": "溅水音效", "Shallower water is waded; deeper water is swum. Dash dives, Jump rises; at the surface Jump leaps out.": "浅水涉水而过，深水需游泳。冲刺下潜，跳跃上浮；在水面时跳跃可跃出水面。" });
Object.assign(RR_TEXT_TRANSLATIONS.ru, { "While swimming": "При плавании", "Swimming": "Плавание", "Swimming (3D maps)": "Плавание (3D-карты)", "Players can swim in deep water": "Игроки могут плавать в глубокой воде", "Float depth": "Глубина плавания", "tiles under the surface": "клеток под поверхностью", "Splash sound": "Звук всплеска", "Shallower water is waded; deeper water is swum. Dash dives, Jump rises; at the surface Jump leaps out.": "Мелкую воду переходят вброд, в глубокой плывут. Бег — нырнуть, Прыжок — всплыть; на поверхности Прыжок выпрыгивает из воды." });
Object.assign(RR_TEXT_TRANSLATIONS.pt, { "While swimming": "Ao nadar", "Swimming": "Natação", "Swimming (3D maps)": "Natação (mapas 3D)", "Players can swim in deep water": "Os jogadores podem nadar em água funda", "Float depth": "Profundidade de flutuação", "tiles under the surface": "quadrados sob a superfície", "Splash sound": "Som de mergulho", "Shallower water is waded; deeper water is swum. Dash dives, Jump rises; at the surface Jump leaps out.": "Água rasa se atravessa a pé; a funda se nada. Correr mergulha, Pular sobe; na superfície Pular salta para fora." });
Object.assign(RR_TEXT_TRANSLATIONS.de, { "While swimming": "Beim Schwimmen", "Swimming": "Schwimmen", "Swimming (3D maps)": "Schwimmen (3D-Karten)", "Players can swim in deep water": "Spieler können in tiefem Wasser schwimmen", "Float depth": "Schwimmtiefe", "tiles under the surface": "Felder unter der Oberfläche", "Splash sound": "Platschgeräusch", "Shallower water is waded; deeper water is swum. Dash dives, Jump rises; at the surface Jump leaps out.": "Flaches Wasser wird durchwatet, tiefes durchschwommen. Rennen taucht, Springen steigt auf; an der Oberfläche springt Springen heraus." });
Object.assign(RR_TEXT_TRANSLATIONS.fr, { "While swimming": "En nageant", "Swimming": "Nage", "Swimming (3D maps)": "Nage (cartes 3D)", "Players can swim in deep water": "Les joueurs peuvent nager en eau profonde", "Float depth": "Profondeur de flottaison", "tiles under the surface": "cases sous la surface", "Splash sound": "Son d’éclaboussure", "Shallower water is waded; deeper water is swum. Dash dives, Jump rises; at the surface Jump leaps out.": "L’eau peu profonde se traverse à pied, la profonde se nage. Courir plonge, Sauter remonte ; en surface, Sauter fait sortir de l’eau." });
Object.assign(RR_TEXT_TRANSLATIONS.el, { "While swimming": "Στο κολύμπι", "Swimming": "Κολύμπι", "Swimming (3D maps)": "Κολύμπι (3D χάρτες)", "Players can swim in deep water": "Οι παίκτες κολυμπούν σε βαθιά νερά", "Float depth": "Βάθος επίπλευσης", "tiles under the surface": "πλακίδια κάτω από την επιφάνεια", "Splash sound": "Ήχος πιτσιλίσματος", "Shallower water is waded; deeper water is swum. Dash dives, Jump rises; at the surface Jump leaps out.": "Τα ρηχά νερά διασχίζονται με τα πόδια, στα βαθιά κολυμπάς. Το Τρέξιμο βουτά, το Άλμα ανεβαίνει· στην επιφάνεια το Άλμα πηδά έξω." });
Object.assign(RR_TEXT_TRANSLATIONS.ko, { "While swimming": "수영 중", "Swimming": "수영", "Swimming (3D maps)": "수영 (3D 맵)", "Players can swim in deep water": "플레이어가 깊은 물에서 수영할 수 있음", "Float depth": "뜨는 깊이", "tiles under the surface": "타일 (수면 아래)", "Splash sound": "물 튀는 소리", "Shallower water is waded; deeper water is swum. Dash dives, Jump rises; at the surface Jump leaps out.": "얕은 물은 걸어서 건너고 깊은 물은 헤엄칩니다. 대시로 잠수, 점프로 상승; 수면에서는 점프로 뛰쳐나옵니다." });
Object.assign(RR_TEXT_TRANSLATIONS.ar, { "While swimming": "أثناء السباحة", "Swimming": "السباحة", "Swimming (3D maps)": "السباحة (خرائط ثلاثية الأبعاد)", "Players can swim in deep water": "يمكن للاعبين السباحة في المياه العميقة", "Float depth": "عمق الطفو", "tiles under the surface": "مربعات تحت السطح", "Splash sound": "صوت الرذاذ", "Shallower water is waded; deeper water is swum. Dash dives, Jump rises; at the surface Jump leaps out.": "يُخاض الماء الضحل وتُسبح في العميق. الركض يغوص والقفز يصعد؛ وعلى السطح يقفز القفز خارج الماء." });
Object.assign(RR_TEXT_TRANSLATIONS.it, { "While swimming": "Nuotando", "Swimming": "Nuoto", "Swimming (3D maps)": "Nuoto (mappe 3D)", "Players can swim in deep water": "I giocatori possono nuotare in acqua profonda", "Float depth": "Profondità di galleggiamento", "tiles under the surface": "caselle sotto la superficie", "Splash sound": "Suono dello schizzo", "Shallower water is waded; deeper water is swum. Dash dives, Jump rises; at the surface Jump leaps out.": "L’acqua bassa si guada, quella profonda si nuota. Correre fa immergere, Saltare fa risalire; in superficie Saltare fa uscire." });
Object.assign(RR_TEXT_TRANSLATIONS.pl, { "While swimming": "Podczas pływania", "Swimming": "Pływanie", "Swimming (3D maps)": "Pływanie (mapy 3D)", "Players can swim in deep water": "Gracze mogą pływać w głębokiej wodzie", "Float depth": "Głębokość unoszenia", "tiles under the surface": "pól pod powierzchnią", "Splash sound": "Dźwięk plusku", "Shallower water is waded; deeper water is swum. Dash dives, Jump rises; at the surface Jump leaps out.": "Płytką wodę się przechodzi, w głębokiej się pływa. Bieg nurkuje, Skok wynurza; na powierzchni Skok wyskakuje z wody." });
Object.assign(RR_TEXT_TRANSLATIONS.id, { "While swimming": "Saat berenang", "Swimming": "Berenang", "Swimming (3D maps)": "Berenang (peta 3D)", "Players can swim in deep water": "Pemain dapat berenang di air dalam", "Float depth": "Kedalaman mengapung", "tiles under the surface": "petak di bawah permukaan", "Splash sound": "Suara cipratan", "Shallower water is waded; deeper water is swum. Dash dives, Jump rises; at the surface Jump leaps out.": "Air dangkal diarungi, air dalam direnangi. Lari untuk menyelam, Lompat untuk naik; di permukaan Lompat keluar dari air." });
Object.assign(RR_TEXT_TRANSLATIONS.vi, { "While swimming": "Khi bơi", "Swimming": "Bơi", "Swimming (3D maps)": "Bơi (bản đồ 3D)", "Players can swim in deep water": "Người chơi có thể bơi ở nước sâu", "Float depth": "Độ sâu nổi", "tiles under the surface": "ô dưới mặt nước", "Splash sound": "Âm thanh té nước", "Shallower water is waded; deeper water is swum. Dash dives, Jump rises; at the surface Jump leaps out.": "Nước nông thì lội, nước sâu thì bơi. Chạy để lặn, Nhảy để nổi lên; trên mặt nước Nhảy để thoát ra." });
Object.assign(RR_TEXT_TRANSLATIONS.th, { "While swimming": "ขณะว่ายน้ำ", "Swimming": "ว่ายน้ำ", "Swimming (3D maps)": "ว่ายน้ำ (แผนที่ 3D)", "Players can swim in deep water": "ผู้เล่นว่ายน้ำในน้ำลึกได้", "Float depth": "ความลึกขณะลอย", "tiles under the surface": "ช่องใต้ผิวน้ำ", "Splash sound": "เสียงน้ำกระเซ็น", "Shallower water is waded; deeper water is swum. Dash dives, Jump rises; at the surface Jump leaps out.": "น้ำตื้นเดินลุย น้ำลึกต้องว่าย วิ่งเพื่อดำ กระโดดเพื่อขึ้น ที่ผิวน้ำกระโดดเพื่อออกจากน้ำ" });
Object.assign(RR_TEXT_TRANSLATIONS.tr, { "While swimming": "Yüzerken", "Swimming": "Yüzme", "Swimming (3D maps)": "Yüzme (3D haritalar)", "Players can swim in deep water": "Oyuncular derin suda yüzebilir", "Float depth": "Yüzme derinliği", "tiles under the surface": "yüzeyin altında karo", "Splash sound": "Su sıçraması sesi", "Shallower water is waded; deeper water is swum. Dash dives, Jump rises; at the surface Jump leaps out.": "Sığ suda yürünür, derin suda yüzülür. Koşma dalar, Zıplama yükselir; yüzeyde Zıplama sudan çıkarır." });

