Object.assign(RR_I18N_STRINGS["pl"], {"terrain.river": "Rzeka", "terrain.riverWidth": "Szerokość", "terrain.riverDepth": "Głębokość", "terrain.hint.river": "Klikaj wzdłuż koryta, zaczynając od źródła. Dwuklik lub Enter układa rzekę; Esc porzuca trasę. Rzeka wycina koryto, płynie w dół i spada tam, gdzie teren się obniża.", "terrain.riverPoints": "Punkty trasy: {count}", "terrain.riverLay": "Ułóż rzekę", "terrain.riverCancel": "Porzuć trasę", "terrain.riverShort": "Kliknij co najmniej dwa punkty wzdłuż trasy.", "terrain.riverNone": "Na tej trasie nie zmieści się rzeka."});
