Object.assign(RR_I18N_STRINGS["pl"], {"vehicle.scenery": "Tylko dekoracja", "vehicle.database": "Pojazdy", "vehicle.add": "Dodaj pojazd", "vehicle.kind": "Typ pojazdu", "vehicle.motorcycle": "Motocykl", "vehicle.model": "Model pojazdu", "vehicle.size": "Długość modelu (pola)", "vehicle.handling": "Prowadzenie", "vehicle.speed": "Prędkość maksymalna (pola/s)", "vehicle.acceleration": "Czas do prędkości maksymalnej (s)", "vehicle.turn": "Średnica skrętu (pola)", "vehicle.brake": "Czas hamowania (s)", "vehicle.coast": "Czas toczenia (s)", "vehicle.reverse": "Prędkość cofania (pola/s)", "vehicle.lean": "Maksymalny przechył (stopnie)", "vehicle.jump": "Wysokość skoku (pola)", "vehicle.place": "Umieść na mapie", "vehicle.event": "Pojazd Reactor (całe zdarzenie)", "vehicle.none": "Nie jest pojazdem Reactor", "vehicle.missing": "brak typu", "vehicle.facing": "Początkowy kierunek", "vehicle.pageFacing": "Kierunek pierwszej strony", "vehicle.board": "Wsiadanie", "vehicle.confirm": "Potwierdź obok pojazdu", "vehicle.command": "Polecenie zdarzenia", "vehicle.key": "Nazwa dla poleceń (opcjonalna)", "vehicle.inherited": "Wygląd z Baza danych → Pojazdy", "vehicle.getOn": "Wsiądź do pojazdu Reactor", "vehicle.getOff": "Wysiądź z pojazdu Reactor", "vehicle.target": "Pojazd", "vehicle.instant": "Pomiń animację wsiadania", "vehicle.wait": "Czekaj na zakończenie", "vehicle.classic": "Pojazd RPG Maker", "vehicle.classEquipment": "Klasa i wyposażenie", "vehicle.noClass": "Bez klasy", "vehicle.incompatible": "niedozwolone przez klasę", "vehicle.baseStats": "Parametry bazowe + wyposażenie (przed cechami)", "vehicle.classSlots": "Sloty wyposażenia pojazdu", "vehicle.customSlots": "Użyj własnego układu pojazdu", "vehicle.slot": "Slot wyposażenia", "vehicle.car": "Samochód", "vehicle.tank": "Czołg", "vehicle.shuttle": "Wahadłowiec", "vehicle.hover": "Poduszkowiec", "vehicle.support": "Motocykle jeżdżą po mapach3D bez zapętlenia, ze swobodnym ruchem. Pozostałe typy są dekoracją.", "vehicle.unsupported": "Ten typ jest dekoracją. Wybierz Motocykl, aby jeździć; istniejące dane zostają.", "vehicle.noModel": "Wybierz model, aby pojazd był widoczny i umożliwiał jazdę.", "vehicle.modelHelp": "Model określa wygląd, koła i siedzenie; brakujące punkty są szacowane. Po zmianie rozmiaru sprawdź pozycję kierowcy.", "vehicle.how": "W Baza danych→Pojazdy wybierz typ i model. Przypisz go do zdarzenia mapy przez Pojazd Reactor. Dotyczy wszystkich stron.", "vehicle.controls": "Spójrz na pojazd i potwierdź, aby wsiąść. Anuluj／Escape hamuje i pozwala wysiąść.", "vehicle.maps": "Podczas jazdy pojazd podróżuje między mapami. Zaparkowany pozostaje tam; tożsamość, pozycja i stan są zapisywane.", "vehicle.commandHelp": "Istniejące polecenia zostają. Po dialogu lub warunku dodaj polecenie wsiadania z karty Reactor, cel this.", "vehicle.targetHelp": "this oznacza bieżące zdarzenie, nearest pobliski pojazd. Można też podać lokalny ID zdarzenia lub nazwę dla poleceń.", "vehicle.classicHelp": "Łódź, Statek i Sterowiec zachowują grafiki, pozycje i polecenia. Mapa0 oznacza brak umieszczenia. Dodatkowe pojazdy Reactor są opcjonalne.", "vehicle.classHelp": "Klasa określa krzywe, umiejętności i dozwolone wyposażenie. Sloty definiuje się w Klasach, kategorie w Typach. Każdy pojazd ma własne zdrowie, sprzęt i stany. Klasa nie włącza walki na pojeździe.", "vehicle.slotHelp": "Układ tylko dla pojazdów tej klasy. Powtarzaj typy dla wielu broni lub modułów. Sloty aktorów zachowują swoje zasady."});
