for (const language of RR_LANGUAGES) {
    const strings = RR_I18N_STRINGS[language.id];
    if (language.id === 'en') continue;
    Object.assign(RR_EVENT_COMMAND_NAMES[language.id], {
        'Get On Reactor Vehicle': strings['vehicle.getOn'],
        'Get Off Reactor Vehicle': strings['vehicle.getOff']
    });
    RR_EVENT_SECTION_NAMES[language.id].Vehicles = strings['vehicle.database'];
}

