for (const [locale, table] of Object.entries(RR_PROP_BUILDER_TEXT)) {
    RR_I18N_STRINGS[locale] = RR_I18N_STRINGS[locale] || {};
    RR_I18N_STRINGS[locale]['menu.propBuilder'] = table['3D Prop Builder'];
    RR_I18N_STRINGS[locale]['forge.propBuilder.description'] = table[RR_PROP_BUILDER_DESCRIPTION];
    RR_TEXT_TRANSLATIONS[locale] = RR_TEXT_TRANSLATIONS[locale] || {};
    for (const [source, text] of Object.entries(table)) { const have = RR_TEXT_TRANSLATIONS[locale][source]; if (!have || have === source) RR_TEXT_TRANSLATIONS[locale][source] = text; }
}
